// MsgServer is the server API for Msg service.
type MsgServer interface {
	// UpdateParams defines a (governance) operation for updating the module
	// parameters. The authority defaults to the x/gov module account.
	UpdateParams(context.Context, *MsgUpdateParams) (*MsgUpdateParamsResponse, error)
	// CreateClass creates a new class (member- or council-gated, fee burned).
	CreateClass(context.Context, *MsgCreateClass) (*MsgCreateClassResponse, error)
	// UpdateClass edits class metadata and payment routing.
	UpdateClass(context.Context, *MsgUpdateClass) (*MsgUpdateClassResponse, error)
	// FreezeClassMetadata freezes class and token metadata (one-way).
	FreezeClassMetadata(context.Context, *MsgFreezeClassMetadata) (*MsgFreezeClassMetadataResponse, error)
	// SetMintPolicy replaces the public mint policy.
	SetMintPolicy(context.Context, *MsgSetMintPolicy) (*MsgSetMintPolicyResponse, error)
	// SetMinters adds and removes class minters.
	SetMinters(context.Context, *MsgSetMinters) (*MsgSetMintersResponse, error)
	// SetMaxSupply lowers (or first sets) the class supply cap.
	SetMaxSupply(context.Context, *MsgSetMaxSupply) (*MsgSetMaxSupplyResponse, error)
	// CloseMinting permanently stops minting.
	CloseMinting(context.Context, *MsgCloseMinting) (*MsgCloseMintingResponse, error)
	// ProposeClassOwner proposes a class ownership handover.
	ProposeClassOwner(context.Context, *MsgProposeClassOwner) (*MsgProposeClassOwnerResponse, error)
	// AcceptClassOwner accepts a proposed handover.
	AcceptClassOwner(context.Context, *MsgAcceptClassOwner) (*MsgAcceptClassOwnerResponse, error)
	// CancelClassOwner withdraws a proposed handover.
	CancelClassOwner(context.Context, *MsgCancelClassOwner) (*MsgCancelClassOwnerResponse, error)
	// DeleteClass deletes an empty class.
	DeleteClass(context.Context, *MsgDeleteClass) (*MsgDeleteClassResponse, error)
	// Mint mints tokens as the class owner or a listed minter.
	Mint(context.Context, *MsgMint) (*MsgMintResponse, error)
	// PublicMint buys tokens under the class's public mint policy.
	PublicMint(context.Context, *MsgPublicMint) (*MsgPublicMintResponse, error)
	// Transfer moves tokens to recipients (or their inboxes).
	Transfer(context.Context, *MsgTransfer) (*MsgTransferResponse, error)
	// AcceptIncoming accepts inbox items.
	AcceptIncoming(context.Context, *MsgAcceptIncoming) (*MsgAcceptIncomingResponse, error)
	// RejectIncoming rejects inbox items.
	RejectIncoming(context.Context, *MsgRejectIncoming) (*MsgRejectIncomingResponse, error)
	// CancelOutgoing withdraws pending items the signer sent.
	CancelOutgoing(context.Context, *MsgCancelOutgoing) (*MsgCancelOutgoingResponse, error)
	// SetReceivePolicy sets the signer's receive policy.
	SetReceivePolicy(context.Context, *MsgSetReceivePolicy) (*MsgSetReceivePolicyResponse, error)
	// Burn destroys tokens and refunds their deposits to the burner.
	Burn(context.Context, *MsgBurn) (*MsgBurnResponse, error)
	// Revoke burns tokens as the class owner, when the class's
	// burn_authorization allows the issuer.
	Revoke(context.Context, *MsgRevoke) (*MsgRevokeResponse, error)
	// UpdateToken replaces a token's metadata (mutable classes only).
	UpdateToken(context.Context, *MsgUpdateToken) (*MsgUpdateTokenResponse, error)
	// FreezeTokenMetadata freezes token metadata (class owner or holder).
	FreezeTokenMetadata(context.Context, *MsgFreezeTokenMetadata) (*MsgFreezeTokenMetadataResponse, error)
	// List offers a token for sale at a fixed SPARK price.
	List(context.Context, *MsgList) (*MsgListResponse, error)
	// UpdateListing changes a listing's price or duration.
	UpdateListing(context.Context, *MsgUpdateListing) (*MsgUpdateListingResponse, error)
	// Delist cancels a listing.
	Delist(context.Context, *MsgDelist) (*MsgDelistResponse, error)
	// Buy purchases a listed token.
	Buy(context.Context, *MsgBuy) (*MsgBuyResponse, error)
	// HideContent hides a class or token (sentinel or council).
	HideContent(context.Context, *MsgHideContent) (*MsgHideContentResponse, error)
	// UnhideContent reverses a hide before appeal.
	UnhideContent(context.Context, *MsgUnhideContent) (*MsgUnhideContentResponse, error)
	// AppealHide appeals a hide through the x/rep jury (ARTIFACT_HIDE).
	AppealHide(context.Context, *MsgAppealHide) (*MsgAppealHideResponse, error)
	// UpdateOperationalParams updates the operational parameter subset.
	UpdateOperationalParams(context.Context, *MsgUpdateOperationalParams) (*MsgUpdateOperationalParamsResponse, error)
	// Issue mints one shared metadata to many recipients (attendance and
	// participation badges). Cheaper than MsgMint for large batches.
	Issue(context.Context, *MsgIssue) (*MsgIssueResponse, error)
	// Renew extends an expiring token's term, by the holder (paying the
	// class) or by the class owner or a listed minter (free).
	Renew(context.Context, *MsgRenew) (*MsgRenewResponse, error)
	// Redeem marks tokens of a redeemable class as redeemed (one-way).
	Redeem(context.Context, *MsgRedeem) (*MsgRedeemResponse, error)
	// LockRoyalty freezes the class royalty split (irreversible).
	LockRoyalty(context.Context, *MsgLockRoyalty) (*MsgLockRoyaltyResponse, error)
	// Reveal discloses a blind-minted token's metadata against the class
	// commitment.
	Reveal(context.Context, *MsgReveal) (*MsgRevealResponse, error)
	// RevealSeed discloses a generative class's seed secret.
	RevealSeed(context.Context, *MsgRevealSeed) (*MsgRevealSeedResponse, error)
	// ProposeMedia offers the holder an additional media version of a token.
	ProposeMedia(context.Context, *MsgProposeMedia) (*MsgProposeMediaResponse, error)
	// AcceptMedia adds a proposed media version to the token.
	AcceptMedia(context.Context, *MsgAcceptMedia) (*MsgAcceptMediaResponse, error)
	// RejectMedia discards a media proposal (holder or class owner).
	RejectMedia(context.Context, *MsgRejectMedia) (*MsgRejectMediaResponse, error)
	// SetDisplayedMedia picks which accepted version the token shows.
	SetDisplayedMedia(context.Context, *MsgSetDisplayedMedia) (*MsgSetDisplayedMediaResponse, error)
	// CreateEdition adds an edition to an EDITIONS class; with a claim it is
	// an impact certificate.
	CreateEdition(context.Context, *MsgCreateEdition) (*MsgCreateEditionResponse, error)
	// MintUnits mints units of an edition.
	MintUnits(context.Context, *MsgMintUnits) (*MsgMintUnitsResponse, error)
	// TransferUnits moves edition units to recipients (or their inboxes).
	TransferUnits(context.Context, *MsgTransferUnits) (*MsgTransferUnitsResponse, error)
	// BurnUnits burns units the signer holds.
	BurnUnits(context.Context, *MsgBurnUnits) (*MsgBurnUnitsResponse, error)
	// RevokeUnits burns a holder's units as the class owner, when the class
	// lets the issuer burn.
	RevokeUnits(context.Context, *MsgRevokeUnits) (*MsgRevokeUnitsResponse, error)
	// ListUnits offers edition units at a fixed per-unit price.
	ListUnits(context.Context, *MsgListUnits) (*MsgListUnitsResponse, error)
	// DelistUnits cancels a unit listing.
	DelistUnits(context.Context, *MsgDelistUnits) (*MsgDelistUnitsResponse, error)
	// BuyUnits buys some or all of a unit listing.
	BuyUnits(context.Context, *MsgBuyUnits) (*MsgBuyUnitsResponse, error)
	// FundEdition pays SPARK to an edition's holders, pro rata (retroactive
	// funding of an impact certificate).
	FundEdition(context.Context, *MsgFundEdition) (*MsgFundEditionResponse, error)
	// ClaimEditionRewards pays out accrued retro funding.
	ClaimEditionRewards(context.Context, *MsgClaimEditionRewards) (*MsgClaimEditionRewardsResponse, error)
	// AddCraftRecipe adds a crafting recipe to a class (until its first craft).
	AddCraftRecipe(context.Context, *MsgAddCraftRecipe) (*MsgAddCraftRecipeResponse, error)
	// RemoveCraftRecipe removes a crafting recipe.
	RemoveCraftRecipe(context.Context, *MsgRemoveCraftRecipe) (*MsgRemoveCraftRecipeResponse, error)
	// Craft burns a recipe's inputs and mints its output to the crafter.
	Craft(context.Context, *MsgCraft) (*MsgCraftResponse, error)
	// OfferRental offers a token's user right for rent.
	OfferRental(context.Context, *MsgOfferRental) (*MsgOfferRentalResponse, error)
	// CancelRentalOffer withdraws a rental offer.
	CancelRentalOffer(context.Context, *MsgCancelRentalOffer) (*MsgCancelRentalOfferResponse, error)
	// AcceptRental rents a token, paying the offer's price.
	AcceptRental(context.Context, *MsgAcceptRental) (*MsgAcceptRentalResponse, error)
	// EndRental ends a rental.
	EndRental(context.Context, *MsgEndRental) (*MsgEndRentalResponse, error)
	// Nest places a token inside another token the signer owns.
	Nest(context.Context, *MsgNest) (*MsgNestResponse, error)
	// Detach takes a nested token out of its parent.
	Detach(context.Context, *MsgDetach) (*MsgDetachResponse, error)
	// SetHarbergerPrice self-assesses a Harberger token's price.
	SetHarbergerPrice(context.Context, *MsgSetHarbergerPrice) (*MsgSetHarbergerPriceResponse, error)
	// ForceBuy buys a Harberger token at its current price.
	ForceBuy(context.Context, *MsgForceBuy) (*MsgForceBuyResponse, error)
	// UpdateUnitListing changes a unit listing's quantity, price and duration.
	UpdateUnitListing(context.Context, *MsgUpdateUnitListing) (*MsgUpdateUnitListingResponse, error)
	// MakeOffer escrows a SPARK offer for a token or any token of a class.
	MakeOffer(context.Context, *MsgMakeOffer) (*MsgMakeOfferResponse, error)
	// CancelOffer withdraws an offer and refunds its escrow.
	CancelOffer(context.Context, *MsgCancelOffer) (*MsgCancelOfferResponse, error)
	// AcceptOffer sells a token to an offer's bidder.
	AcceptOffer(context.Context, *MsgAcceptOffer) (*MsgAcceptOfferResponse, error)
	// StartAuction puts a token up for an English auction.
	StartAuction(context.Context, *MsgStartAuction) (*MsgStartAuctionResponse, error)
	// Bid places an escrowed bid on an auction.
	Bid(context.Context, *MsgBid) (*MsgBidResponse, error)
	// SettleAuction settles an ended auction (anyone may sign).
	SettleAuction(context.Context, *MsgSettleAuction) (*MsgSettleAuctionResponse, error)
	// CancelAuction withdraws an auction nobody has bid on.
	CancelAuction(context.Context, *MsgCancelAuction) (*MsgCancelAuctionResponse, error)
}

